import 'dart:convert';

/// A tiny (64x64, 2s, ~9KB) real H.264/AAC MP4 — small enough to embed as a
/// constant, and a genuinely decodable video so `player.surface` scenarios
/// (Fase 11) exercise a real player rather than an opaque byte blob. Fixed
/// content in, fixed bytes out: the same run of the command below always
/// produces this exact file, which is what "deterministic bytes" means for
/// GET /stream/{version_id} — not that it's regenerated per request.
///
/// Regenerate with (ffmpeg 9.x, libx264/aac):
/// ```
/// ffmpeg -y -f lavfi -i "color=c=0x2b6cb0:s=64x64:d=2:r=8" \\
///   -f lavfi -i "sine=frequency=440:duration=2" \\
///   -c:v libx264 -preset veryslow -crf 32 -pix_fmt yuv420p \\
///   -profile:v baseline -level 3.0 -c:a aac -b:a 24k -ar 22050 -ac 1 \\
///   -movflags +faststart sample_media.mp4
/// base64 -i sample_media.mp4
/// ```
const String sampleMediaMp4Base64 =
    '';

final List<int> sampleMediaMp4Bytes = base64Decode(sampleMediaMp4Base64);
